import csv
vals={}
for r in csv.DictReader(open(VALUES_CSV)):
    vals.setdefault(r['timeseries_id'],[]).append((r['timestamp'],float(r['value'])))

fans={'SupplyFan_AHU01':'47f1370e-62d8-56c6-8ae6-d34fa69cf177',
      'SupplyFan_AHU03':'f0a0044c-9c90-58fc-b425-307d0c874a2a'}
day='2018-07-16'
res={}
for name,ts in fans.items():
    data=vals[ts]
    record_high=max(v for _,v in data)
    dayvals=[v for t,v in data if t.startswith(day)]
    dayhigh=max(dayvals)
    res[name]=dayhigh/record_high
    print(name,'dayhigh',dayhigh,'record_high',record_high,'ratio',dayhigh/record_high)
print(max(res,key=res.get))
